<script setup lang="ts">
import { computed } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ProjectReader, type DramaGlobal, type DramaUsage } from '../../platform/project-reader'
import DramaDocument from './DramaDocument.vue'
import DramaFile from './DramaFile.vue'
import DramaVersions from './DramaVersions.vue'
import DramaTips from './DramaTips.vue'
import DramaPublication from './DramaPublication.vue'
const props = defineProps<{ reader: ProjectReader; tab: string }>()
const route = useRoute(), router = useRouter(), q = (key: string) => typeof route.query[key] === 'string' ? route.query[key] as string : ''
const project = computed(() => props.reader.project!), drama = computed(() => props.reader.content!.ai_short_drama!)
const kinds = [{ key: 'script', label: '剧本' }, { key: 'character', label: '人物' }, { key: 'wardrobe', label: '服装造型' }, { key: 'prop', label: '道具' }, { key: 'location', label: '场景' }, { key: 'sound', label: '声音' }, { key: 'music', label: '配乐' }]
const kindName = (key: string) => kinds.find(k => k.key === key)?.label || '设定'
const material = computed(() => drama.value.globals.find(g => g.key === q('material')))
const state = computed(() => q('state') ? material.value?.states.find(s => s.key === q('state')) : material.value?.states.find(s => s.key === material.value?.versions.find(v => v.key === q('version'))?.state_key) || material.value?.states[0])
const episode = computed(() => q('episode') ? drama.value.episodes.find(e => e.key === q('episode')) : drama.value.episodes[0])
const scene = computed(() => episode.value?.scenes.find(s => s.key === q('scene')))
const shot = computed(() => scene.value?.shots.find(s => s.key === q('shot')))
const delivery = computed(() => drama.value.deliverables.find(d => d.key === q('deliverable')))
const filtered = computed(() => drama.value.globals.filter(g => (props.tab === 'script' || g.kind !== 'script') && (!q('kind') || g.kind === q('kind')) && matches(g.name + ' ' + (g.description || ''))))
const matches = (text: string) => !q('find') || text.includes(q('find'))
function link(change: Record<string, string | undefined>) { return { path: route.path, query: { ...route.query, ...change } } }
function materialLink(g: DramaGlobal, version?: string, state?: string) { return link({ tab: 'materials', material: g.key, state, version, find: undefined, kind: undefined, compare: undefined, episode: undefined, scene: undefined, shot: undefined, deliverable: undefined }) }
const back = computed(() => link({ material: undefined, state: undefined, version: undefined, compare: undefined, shot: undefined, scene: undefined, deliverable: undefined }))
const target = computed(() => [props.tab, q('material'), q('state'), q('episode'), q('scene'), q('shot'), q('deliverable'), q('version')].join('/'))
const usages = computed(() => drama.value.usages.filter(u => material.value ? u.global_key === material.value.key : shot.value ? u.target.episode_key === episode.value?.key && (!u.target.scene_key || u.target.scene_key === scene.value?.key) && (!u.target.shot_key || u.target.shot_key === shot.value.key) : false))
function usageLabel(u: DramaUsage) { const e = drama.value.episodes.find(e => e.key === u.target.episode_key), s = e?.scenes.find(s => s.key === u.target.scene_key), sh = s?.shots.find(sh => sh.key === u.target.shot_key); return [e?.title, s?.title, sh?.title, u.segment?.label].filter(Boolean).join(' · ') }
function usageMaterial(u: DramaUsage) { const g = drama.value.globals.find(g => g.key === u.global_key)!; return [g.name, g.states.find(s => s.key === u.state_key)?.name || '状态未整理', g.versions.find(v => v.key === u.version_key)?.label || '制作版本未选定'].join(' · ') }
function cover(g: DramaGlobal) { const v = g.versions.find(v => g.selected_versions.some(s => s.version_key === v.key)); return v?.file_refs.find(f => ['image', 'preview', 'portrait'].includes(f.purpose))?.file_id || (!g.versions.length ? g.file_ids[0] : null) }
</script>
<template>
  <div class="short-drama">
    <template v-if="q('material')">
      <RouterLink class="btn" :to="back">返回资料列表</RouterLink><p v-if="!material" class="empty">当前修订没有这项资料。</p>
      <p v-else-if="q('state') && !state" class="empty">当前修订没有这个状态，请返回资料列表重新选择。</p>
      <template v-else>
        <header><p class="muted">{{ kindName(material.kind) }}</p><h2>{{ material.name }}</h2><p class="prose">{{ material.description || '说明尚未填写。' }}</p></header>
        <div class="production-cols"><div class="stack">
          <section class="panel"><h2>文字设定与生成依据</h2><p v-if="!material.definition_refs.length" class="muted">设定依据尚未关联。</p><DramaDocument v-for="(r, i) in material.definition_refs" :key="`${r.file_id}:${i}`" :reader="reader" :file-id="r.file_id" :title="`设定资料 ${i + 1}`" /><div class="links"><RouterLink v-for="g in drama.globals.filter(g => material?.input_global_keys.includes(g.key))" :key="g.key" :to="materialLink(g)">{{ g.name }} →</RouterLink></div></section>
          <section class="panel"><h2>{{ material.kind === 'location' ? '场景状态：时段、天气与光源' : '剧情状态与连续性细节' }}</h2><p v-if="!material.states.length" class="muted">状态尚未整理，不默认视为干净、完好或日景。</p><template v-else><label>查看状态<select :value="state?.key" @change="router.replace(link({ state: ($event.target as HTMLSelectElement).value, version: undefined, compare: undefined }))"><option v-for="s in material.states" :key="s.key" :value="s.key">{{ s.name }}</option></select></label><template v-if="state"><DramaDocument v-for="(r, i) in state.definition_refs" :key="`${r.file_id}:${i}`" :reader="reader" :file-id="r.file_id" :title="`状态依据 ${i + 1}`" /><div v-for="mark in state.marks" :key="mark.key" class="row"><strong>{{ mark.part }} · {{ mark.side }}</strong><p class="prose">{{ mark.description }}</p><DramaDocument v-for="(r, i) in mark.reference_refs" :key="`${r.file_id}:${i}`" :reader="reader" :file-id="r.file_id" :title="`细节参考 ${i + 1}`" /></div><p v-if="!state.marks.length" class="muted">本状态没有额外登记污损或破损标记；环境以状态依据为准。</p></template></template></section>
          <DramaVersions :reader="reader" :versions="material.versions.filter(v => !state || v.state_key === state.key)" :selections="material.selected_versions" />
          <section v-if="!material.versions.length && material.file_ids.length" class="panel"><h2>已有成果</h2><DramaFile v-for="(id, i) in material.file_ids" :key="id" :reader="reader" :file-id="id" :label="`成果 ${i + 1}`" /></section>
          <section v-if="material.reference_file_ids.length" class="panel"><h2>参考资料</h2><DramaFile v-for="(id, i) in material.reference_file_ids" :key="id" :reader="reader" :file-id="id" :label="`参考 ${i + 1}`" /></section>
        </div><aside class="stack"><section class="panel"><h2>使用位置</h2><p v-if="!usages.length" class="muted">尚未关联使用位置。</p><div v-for="u in usages" :key="u.key" class="row"><RouterLink :to="link({ tab: 'production', material: undefined, state: undefined, version: undefined, find: undefined, kind: undefined, compare: undefined, episode: u.target.episode_key, scene: u.target.scene_key, shot: u.target.shot_key })">{{ usageLabel(u) }} →</RouterLink><p class="muted">{{ usageMaterial(u) }}</p><p class="prose">{{ u.description }}</p></div></section><DramaTips :project-id="project.project_id" :revision-id="project.revision_id" :target="target" /></aside></div>
      </template>
    </template>
    <template v-else-if="q('shot')">
      <RouterLink class="btn" :to="back">返回镜头列表</RouterLink><p v-if="!shot" class="empty">当前修订没有这个镜头。</p>
      <div v-else class="production-cols"><div class="stack"><section class="panel"><h2>{{ shot.title }}</h2><p class="prose">{{ shot.overview || '镜头说明尚未填写。' }}</p><p class="muted">{{ shot.duration_seconds == null ? '剧本时长未填写' : `剧本预算 ${shot.duration_seconds} 秒` }}</p><DramaDocument v-for="(r, i) in shot.definition_refs" :key="`${r.file_id}:${i}`" :reader="reader" :file-id="r.file_id" :title="`剧本与连续性依据 ${i + 1}`" /><div v-for="s in [...shot.segments].sort((a, b) => a.order - b.order)" :key="s.key" class="row">{{ s.order }} · {{ s.label }}</div></section><DramaVersions :reader="reader" :versions="shot.versions" :selections="shot.selected_versions" /><section v-if="!shot.versions.length && shot.result_file_ids.length" class="panel"><h2>已有结果 · 版本关系未整理</h2><DramaFile v-for="(id, i) in shot.result_file_ids" :key="id" :reader="reader" :file-id="id" :label="`镜头结果 ${i + 1}`" /></section></div><aside class="stack"><section class="panel"><h2>固定素材与场景状态</h2><p v-if="!usages.length" class="muted">素材、白模与灯光输入尚未关联。</p><div v-for="u in usages" :key="u.key" class="row"><RouterLink :to="materialLink(drama.globals.find(g => g.key === u.global_key)!, u.version_key || undefined, u.state_key || undefined)">{{ usageMaterial(u) }} →</RouterLink><p class="muted">{{ u.segment?.label || '场次／整镜使用' }}</p></div></section><section v-if="shot.continuity_keys.length" class="panel"><h2>连续性核对</h2><div v-for="c in drama.continuity.filter(c => shot?.continuity_keys.includes(c.key))" :key="c.key" class="row"><h3>{{ c.name }}</h3><p class="prose">{{ c.description }}</p><DramaDocument v-for="(r, i) in c.definition_refs" :key="`${r.file_id}:${i}`" :reader="reader" :file-id="r.file_id" :title="`连续性资料 ${i + 1}`" /></div></section><DramaTips :project-id="project.project_id" :revision-id="project.revision_id" :target="target" /></aside></div>
    </template>
    <template v-else-if="tab === 'delivery'">
      <template v-if="q('deliverable')"><RouterLink class="btn" :to="back">返回成果列表</RouterLink><template v-if="delivery"><h2>{{ delivery.title }}</h2><p class="prose">{{ delivery.description }}</p><DramaVersions :reader="reader" :versions="delivery.versions" :selected-key="delivery.selected_version_key" /><section class="panel"><h2>实际交付记录</h2><p v-if="!delivery.delivery_record_file_ids.length" class="muted">尚未登记实际交付。导出或下载不代表客户已收到。</p><DramaDocument v-for="(id, i) in delivery.delivery_record_file_ids" :key="id" :reader="reader" :file-id="id" :title="`交付记录 ${i + 1}`" /></section><section v-if="!delivery.versions.length" class="panel"><h2>已有文件</h2><DramaFile v-for="(id, i) in delivery.file_ids" :key="id" :reader="reader" :file-id="id" :label="`成果文件 ${i + 1}`" /></section><DramaTips :project-id="project.project_id" :revision-id="project.revision_id" :target="target" /></template><p v-else class="empty">当前修订没有这项成果。</p></template>
      <template v-else><h2>成果与交付</h2><p class="muted">成片、工程与交付包各自固定版本；新候选不会改变历史成片。</p><div class="material-grid"><RouterLink v-for="d in drama.deliverables" :key="d.key" class="material-card" :to="link({ deliverable: d.key, version: undefined, compare: undefined })"><h3>{{ d.title }}</h3><p class="prose">{{ d.description }}</p><p class="muted">{{ d.versions.find(v => v.key === d.selected_version_key)?.label || '当前选用未整理' }} · {{ d.delivery_record_file_ids.length ? '有交付记录' : '尚无交付记录' }}</p></RouterLink></div><p v-if="!drama.deliverables.length" class="empty">尚未登记成果项。</p><section v-for="e in drama.episodes.filter(e => e.output_file_id || e.edit_file_id)" :key="e.key" class="panel"><h3>{{ e.title }} · 已有分集文件</h3><DramaFile v-if="e.output_file_id" :reader="reader" :file-id="e.output_file_id" label="成片" /><DramaFile v-if="e.edit_file_id" :reader="reader" :file-id="e.edit_file_id" label="编辑工程" /></section></template>
    </template>
    <template v-else>
      <header class="section-head"><div><h2>{{ tab === 'script' ? '剧本与设定' : tab === 'materials' ? '素材设定' : '镜头制作' }}</h2><p class="muted">{{ tab === 'script' ? reader.content?.overview || '剧本正文与全局制作设定共用同一项目。' : tab === 'materials' ? '先查看状态与制作依据，再比较同一素材的候选版本。' : '按集、场、镜头查看固定输入与每轮修改。' }}</p></div><input type="search" aria-label="搜索当前内容" placeholder="搜索名称或说明" :value="q('find')" @input="router.replace(link({ find: ($event.target as HTMLInputElement).value || undefined }))"></header>
      <template v-if="tab !== 'production'"><DramaDocument v-if="tab === 'script'" :reader="reader" :file-id="drama.script_file_id" title="剧本正文" /><nav class="filters" aria-label="资料分类"><RouterLink :class="{ active: !q('kind') }" :to="link({ kind: undefined })">全部</RouterLink><RouterLink v-for="k in kinds.filter(k => tab === 'script' || k.key !== 'script')" :key="k.key" :class="{ active: q('kind') === k.key }" :to="link({ kind: k.key })">{{ k.label }}</RouterLink></nav><div class="material-grid"><article v-for="g in filtered" :key="g.key" class="material-card"><small>{{ kindName(g.kind) }}</small><h3><RouterLink :to="link({ material: g.key, state: undefined, version: undefined, compare: undefined })">{{ g.name }} →</RouterLink></h3><div v-if="cover(g)" class="card-preview"><DramaFile :reader="reader" :file-id="cover(g)!" :label="g.name" /></div><p class="prose">{{ g.description || '查看设定与关联内容' }}</p><p class="muted">{{ g.states.length }} 种剧情状态 · {{ g.versions.length }} 个制作版本</p></article></div><p v-if="!filtered.length" class="empty">暂无匹配资料。</p></template>
      <template v-if="tab !== 'materials'"><nav class="filters" aria-label="分集"><RouterLink v-for="e in drama.episodes" :key="e.key" :class="{ active: e.key === episode?.key }" :to="link({ episode: e.key, scene: undefined, shot: undefined })">{{ e.title }}</RouterLink></nav><section v-if="episode" class="panel"><h2>{{ episode.title }}</h2><p class="prose">{{ episode.overview }}</p><DramaDocument v-if="tab === 'script' && episode.script_file_id" :reader="reader" :file-id="episode.script_file_id" title="分集剧本" /><div v-for="s in episode.scenes" :key="s.key" class="row"><h3>{{ s.title }}</h3><p class="prose">{{ s.overview }}</p><DramaDocument v-for="(r, i) in s.definition_refs" :key="`${r.file_id}:${i}`" :reader="reader" :file-id="r.file_id" :title="`场次设定 ${i + 1}`" /><div class="shot-list"><RouterLink v-for="sh in s.shots.filter(sh => matches(sh.title + ' ' + (sh.overview || '')))" :key="sh.key" :to="link({ scene: s.key, shot: sh.key, episode: episode.key, version: undefined, compare: undefined })"><strong>{{ sh.title }}</strong><span class="muted">{{ sh.duration_seconds == null ? '时长待定' : sh.duration_seconds + ' 秒' }} · {{ sh.versions.length ? sh.versions.length + ' 个制作版本' : '制作未开始' }}</span></RouterLink></div></div></section><p v-else class="empty">尚未整理分集与镜头。</p><section v-if="tab === 'script' && drama.continuity.length" class="panel"><h2>全局连续性设定</h2><div v-for="c in drama.continuity" :key="c.key" class="row"><h3>{{ c.name }}</h3><p class="prose">{{ c.description }}</p><DramaDocument v-for="(r, i) in c.definition_refs" :key="`${r.file_id}:${i}`" :reader="reader" :file-id="r.file_id" :title="`连续性资料 ${i + 1}`" /></div></section></template>
      <DramaTips :project-id="project.project_id" :revision-id="project.revision_id" :target="target" />
    </template>
    <DramaPublication v-if="tab === 'delivery' || material" :reader="reader" :candidates="drama.world_candidates.filter(c => material ? c.source.kind === 'global' && c.source.key === material.key : delivery ? c.source.kind === 'deliverable' && c.source.key === delivery.key : true)" />
  </div>
</template>
<style scoped>
.short-drama { display: grid; gap: 20px; min-width: 0; overflow-wrap: anywhere; }.panel { background: var(--shell-panel); border: 1px solid var(--line); border-radius: 8px; padding: 20px; min-width: 0; }h2 { font-size: 18px; margin-bottom: 12px; }.panel h2 { font-size: 15px; }h3 { font-size: 15px; margin: 8px 0; }.muted,small { color: var(--muted); font-size: 13px; line-height: 1.85; }.prose { white-space: pre-wrap; line-height: 1.85; }.section-head { display: flex; align-items: start; justify-content: space-between; gap: 20px; }.production-cols { display: grid; grid-template-columns: minmax(0, 1fr) 260px; gap: 20px; align-items: start; }.production-cols > *, .stack { min-width: 0; }.stack { display: grid; gap: 18px; }.material-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 16px; }.material-card { display: block; background: var(--shell-panel); border: 1px solid var(--line); border-radius: 8px; padding: 20px; min-width: 0; }.material-card:hover { border-color: var(--accent); }.card-preview { max-width: 280px; margin: 14px 0; }.filters,.links { display: flex; gap: 10px; flex-wrap: wrap; }.filters a { border: 1px solid var(--line); padding: 7px 12px; border-radius: 8px; }.filters a.active { background: var(--subtle); color: var(--ink); }.links a { color: var(--accent); }.row { border-top: 1px solid var(--line); margin-top: 14px; padding-top: 14px; }.shot-list { display: grid; gap: 10px; margin-top: 14px; }.shot-list a { display: flex; flex-wrap: wrap; justify-content: space-between; gap: 10px; padding: 12px; border: 1px solid var(--line); border-radius: 8px; }.empty { color: var(--muted); padding: 26px; border: 1px dashed var(--line); border-radius: 8px; }.btn { justify-self: start; }input,select { border: 1px solid var(--line); background: var(--panel); color: var(--ink); padding: 10px; border-radius: 8px; max-width: 100%; }label { display: grid; gap: 8px; }@media(max-width:1100px) { .production-cols { grid-template-columns: minmax(0,1fr); } }@media(max-width:700px) { .material-grid { grid-template-columns: minmax(0,1fr); }.section-head { flex-direction: column; }input { width: 100%; }.panel,.material-card { padding: 16px; } }
</style>
